*/
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/idAssgnStat.do",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_idAssgn=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil50200n.tx_searchCorpListByBeginIndex" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_idAssgn_fmt_comNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_idAssgn_fmt_comNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_idAssgn");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listTpClssCd") ?? '') : '');
        if (['00',''].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "comNm") : '') ?? '') + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_idAssgn.comNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.viewDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo
 * @returns
 * @hidden N
*/
scwin.viewDetail = async function (bzProcsNo) {
    /* sdd-asis-lifecycle:begin viewDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/listInvstg/clmSchdlNoti.do?method=loadDetail&bzCd=1';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'loadDetail');
    await scwin.tx_viewDetail();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openAssgnPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openAssgnPop = async function () {
    /* sdd-asis-lifecycle:begin openAssgnPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let url = '/jldfil50210/jldfil50210.xml';
    const tp = "konex";
    if (tp !== '') {
        w = '500';
        h = '300';
        l = screen.width / 2 - w / 2;
        t = screen.height / 2 - h / 2;
        if (tp === 'konex') {
            url = '/jldfil50210/jldfil50210.xml?method=choiceAssgnTp&assgnTp=' + 'konex';
        }
        await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "assgnPop", scrollbars: false, resizable: false, width: "500", height: "320", type: "pageFramePopup" }, { method: "choiceAssgnTp", assgnTp: "konex" });
    } else {
        await $c.win.alert('법인 배정 구분을 선택 하십시오.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
