    const pageIndex = $c.util.getComponent('dma_viewDetailReq').get('pageIndex');
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchCorpListByBeginIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchCorpListByBeginIndex = async function () {
    /* sdd-asis-lifecycle:begin searchCorpListByBeginIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.prelistPageForm || { elements: [] }).action = "/listInvstg/idAssgnStat.do";
    { const nr = await scwin.tx_searchCorpListByBeginIndex(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil50200/jldfil50200.xml"); } };
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_52_onclick
 * @author Inswave
